try{const saved=JSON.parse(sessionStorage.getItem('relaxe-search-fixtures-v1')||'{}');for(const key of ['weekendreader','guest'])if(Array.isArray(saved.histories?.[key]))histories[key]=saved.histories[key];const remembered=saved.contexts?.[account];if(remembered){query=typeof remembered.query==='string'?remembered.query:'';scope=['all','community','user','multi'].includes(remembered.scope)?remembered.scope:'all';kind=['posts','communities','people'].includes(remembered.kind)?remembered.kind:'posts';community=remembered.community||'';userTarget=remembered.userTarget||'ridgewalker';privacy=Boolean(remembered.privacy)}}catch{/* Keep the built-in fixture on unavailable storage. */}
const linkedUser=linkedStudy.get('user');if(linkedUser&&/^[A-Za-z0-9_-]{3,20}$/.test(linkedUser)){userTarget=linkedUser;scope='user';N('search-scope').options[2].textContent='Posts by '+userTarget}
const linkedSubreddit=linkedStudy.get('subreddit');if(linkedSubreddit&&/^[A-Za-z0-9_]{2,21}$/.test(linkedSubreddit)){community=linkedSubreddit;scope='community';N('search-scope').options[1].textContent=community}
for(const name of ['click','input','change'])document.addEventListener(name,()=>queueMicrotask(saveSearchFixture));
window.addEventListener('beforeunload',saveSearchFixture);
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==parent)return;if(event.data?.type==='relaxe-open-search')openSearch();else if(event.data?.type==='relaxe-shell-theme'){for(const [key,value]of Object.entries(event.data.tokens||{}))if(key.startsWith('--')&&typeof value==='string')N('nav-phone').style.setProperty(key,value);N('nav-phone').style.setProperty('--shared-bar-height',event.data.inset+'px');positionDialogs()}});
if(embeddedSearch){N('screen-back').addEventListener('click',event=>{event.stopImmediatePropagation();parent.postMessage({type:'relaxe-search-exit'},location.origin)},true);document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!N('search-sheet').open)parent.postMessage({type:'relaxe-search-exit'},location.origin)});showDestination('home');applyTheme();openSearch()}
else if(linkedUser){showDestination('home');applyTheme();openSearch()}
else if(linkedSubreddit){showDestination('community');applyTheme();openSearch()}
else{showDestination(['home','saved','inbox','profile','subscriptions','multireddits'].includes(linkedStudy.get('destination'))?linkedStudy.get('destination'):'home');applyTheme()}
